from __future__ import annotations

# TODO: Could be replace with taf.internal.robot_typecasts once robotframework dependency is removed
from robot.utils.robottime import timestr_to_secs
from taf.internal.aliasing import aliasing_scope
from taf.transport.ssh.connection import SSHConnection

from ..client.telnetclient import TelnetClient
from ..interactor.notifier import Notifier
from ..ssh import SshConnectionAdapter
from ..utils.settings import ConnectionSettings
from ..wts.edaemon import Edaemon
from ..wts.egate import Egate
from ..wts.state_machine import WTSStateMachine


class WTSCommonInterface:

    def __init__(self):
        super(WTSCommonInterface, self).__init__()
        self.wts_lookup_handler, self.wts_store = aliasing_scope(
            name=__name__, lookup_arg="alias", lookup_type=WTSStateMachine
        )
        self.edaemon_lookup_handler, self.edaemon_store = aliasing_scope(
            name=__name__, lookup_arg="alias", lookup_type=Edaemon
        )
        self.egate_lookup_handler, self.egate_store = aliasing_scope(
            name=__name__, lookup_arg="alias", lookup_type=Egate
        )
        self.notifier = Notifier()
        self.connection_settings = {}

    @property
    def edaemon_aliases(self) -> list[str]:
        return list(self.edaemon_store._store.keys())

    @property
    def egate_aliases(self) -> list[str]:
        return list(self.egate_store._store.keys())

    @property
    def wts_aliases(self) -> list[str]:
        return list(self.wts_store._store.keys())

    def _configure_ssh_connection(
        self,
        host_ip: str,
        ssh_username: str,
        ssh_password: str,
        ssh_port: int,
        look_for_keys: bool = True,
    ) -> ConnectionSettings:
        connection_settings = ConnectionSettings()
        connection_settings.host_ip = host_ip
        connection_settings.ssh_username = ssh_username
        connection_settings.ssh_password = ssh_password
        connection_settings.ssh_port = int(ssh_port) if ssh_port is not None else None
        connection_settings.look_for_keys = look_for_keys
        return connection_settings

    def _configure_ssh_connection_for_alias(
        self,
        host_ip: str,
        ssh_username: str,
        ssh_password: str,
        ssh_port: int,
        look_for_keys: bool,
        alias: str,
    ) -> None:
        self.connection_settings[alias] = self._configure_ssh_connection(
            host_ip, ssh_username, ssh_password, ssh_port, look_for_keys
        )

    def _configure_ssh_connection_to_enb(
        self,
        enb_ip: str,
        enb_username: str,
        enb_password: str,
        alias: str,
        look_for_keys: bool = True,
    ) -> None:
        settings = self._get_connection_settings_for_alias(alias)
        settings.enb_ip = enb_ip
        settings.enb_username = enb_username
        settings.enb_password = enb_password
        settings.look_for_keys = look_for_keys

    def _init_connection_parameters(self, alias: str) -> None:
        self.connection_settings[alias] = ConnectionSettings()

    def _to_secs(self, value: str) -> int | None:
        if value is None:
            return None
        return timestr_to_secs(value)

    def _create_ssh_client_from_settings(
        self, settings: ConnectionSettings, proxy: SSHConnection | None = None
    ) -> SshConnectionAdapter:
        client = SshConnectionAdapter()
        client.connect(
            hostname=settings.ssh_connection_params["host"],
            username=settings.ssh_login_params["username"],
            password=settings.ssh_login_params["password"],
            port=settings.ssh_connection_params["port"],
            timeout=settings.ssh_connection_params["timeout"],
            look_for_keys=settings.ssh_login_params["look_for_keys"],
            proxy=proxy,
        )
        return client

    def _get_connection_settings_for_alias(self, alias: str) -> ConnectionSettings:
        if alias in self.connection_settings:
            settings = self.connection_settings[alias]
        else:
            settings = ConnectionSettings()
            self.connection_settings[alias] = settings
        return settings

    def _create_ssh_client_for_alias(self, alias: str) -> SshConnectionAdapter:
        settings = self._get_connection_settings_for_alias(alias)
        return self._create_ssh_client_from_settings(settings)

    def _create_telnet_client_from_settings(
        self, settings: ConnectionSettings, port: int
    ) -> TelnetClient:
        settings.telnet_port = int(port) if port is not None else None
        return TelnetClient(**settings.telnet_params)

    def _create_telnet_client_for_alias(self, port: int, alias: str) -> TelnetClient:
        settings = self._get_connection_settings_for_alias(alias)
        return self._create_telnet_client_from_settings(settings, port)

    def _notify_extenders(
        self, egate: Egate, alias: str, extenders: list[str] | str
    ) -> None:
        if isinstance(extenders, str):
            extenders = [extenders]
        self.notifier.egate_created(egate, alias, *extenders)

    def _create_egate(
        self,
        port: int,
        ssh_client: SshConnectionAdapter,
        telnet_client: TelnetClient,
        tool_dir: str,
        lua_dirs: list | None = None,
    ) -> Egate:
        lua_dirs = lua_dirs or []
        egate = Egate(ssh_client=ssh_client, telnet=telnet_client, port=int(port))
        egate.tool_dir = tool_dir
        for each in lua_dirs:
            egate.lua_dirs.append(each)
        return egate

    def _create_edaemons(
        self, ports: list[int], ssh_client: SshConnectionAdapter, tool_dir: list
    ) -> list[Edaemon]:
        edaemons = []
        for index, port in enumerate(ports):
            edaemon = Edaemon(ssh_client=ssh_client, port=int(port))
            edaemon.tool_dir = tool_dir
            edaemons.append(edaemon)
        return edaemons

    def _collect_logs(
        self, wts: WTSStateMachine, unzip: bool | None, subdirectory: str | None
    ) -> None:
        subdirectory = None if subdirectory is None else str(subdirectory)
        if wts.edaemons:
            files_list = [
                "'{}'/edaemon.log",
                "'{}'/edaemon.log.*",
                "'{}'/mme_*.log.*",
                "'{}'/pgw_*.log.*",
                "'{}'/sgw_*.log.*",
                "'{}'/uec_*.log.*",
                "'{}'/enb_*.log.*",
            ]
            wts.get_edaemons_logs(
                files_list, bool(unzip) if unzip is not None else None, subdirectory
            )
        if wts.egates:
            files_list = ["'{}'/egate.log*", "'{}'/egate_console.log*"]

            wts.get_egates_logs(
                files_list, bool(unzip) if unzip is not None else None, subdirectory
            )
